            const lens = c.createRadialGradient(cx, cy, W * .12, cx, cy, W * .46); lens.addColorStop(0, 'rgba(2,10,12,.92)'); lens.addColorStop(.7, 'rgba(4,18,20,.75)'); lens.addColorStop(.93, 'rgba(40,90,88,.22)'); lens.addColorStop(1, 'rgba(0,0,0,0)')
