            for (const [rr, al] of [[1.24, .35], [1.18, .18]]) { c.strokeStyle = `rgba(120,230,215,${al})`; c.lineWidth = 1; c.beginPath(); c.arc(cx, cy, R * rr, 0, 7); c.stroke() }
